/* The CPG's palettes as constant data (fork, docs/development/specs/04-palette-table.md): the 184 catalogue entries of the MPC Chord
 * Progression Generator, each a palette of 16 chords in its Classic style with a starting order, and a palette per Cadenza scale from
 * the CPG's Scale Mode. src/cpg_palettes.c is generated by tools/cpg/generate.sh from the pinned submodule and committed; CI
 * regenerates it and fails on any difference. Linked by the plugin's front end only, never by the core (S04-D11). Lookups only:
 * no allocation, no state. */
#pragma once
#include <stdint.h>
#include "theory.h"

#define CPG_PADS 16        /* chords in a palette */
#define CPG_MAX_BARS 16    /* bars in a laid-out starting order */

/* A catalogue chord, independent of the project's key and scale (S04-D4): theory.h's palette chord, which the core holds by value (spec
 * 05). Spice: the CPG's harmonic gradient, row 1 the foundation, row 4 the spiciest */
typedef theory_palette_chord_t cpg_chord_t;

/* A catalogue entry. Its chords packed two bytes each (cpg_chord unpacks them); its starting order laid out by decision 4's rule
 * (S04-D9), one palette index a bar, `bars` of them (1, 2, 4, 8 or 16), 4 bits each, the first bar in the low nibble. No pointer: the
 * nickname is an offset into one block of text (cpg_nickname), so the table needs no relocation in the shared object */
typedef struct {
    uint32_t id;                         /* S04-D8: FNV-1a of "genre|template value" */
    unsigned short nick;                 /* cpg_nickname's offset */
    unsigned char genre, minor, bars;    /* genre: cpg_genre_name's index; minor: the CPG's templateTonality is minor */
    unsigned char chord[CPG_PADS][2];
    unsigned char order[CPG_MAX_BARS / 2];
} cpg_entry_t;

/* A scale palette's chord (S04-D5), as a slot holds it in a project of that scale: a degree, a source (0 for every Scale Mode chord,
 * measured), a colour */
typedef struct { signed char deg, src, colour; } cpg_scale_chord_t;

int cpg_count(void);                            /* 184 */
const cpg_entry_t *cpg_entry(int i);            /* 0..cpg_count() - 1, in the CPG's genre and template order; else NULL */
const cpg_entry_t *cpg_find(uint32_t id);       /* NULL for none */
int cpg_genre_count(void);                      /* 22 */
const char *cpg_genre_name(int g);              /* "Pop/Rock"; NULL out of range */
const char *cpg_nickname(const cpg_entry_t *e);  /* the CPG's English nickname, UTF-8 (S04-D10): "Axis of Awesome" */
cpg_chord_t cpg_chord(const cpg_entry_t *e, int k);              /* chord k (0..15) of e */
int cpg_order(const cpg_entry_t *e, unsigned char out[CPG_MAX_BARS]);   /* the bars; out: a palette index a bar */
int cpg_chord_src(cpg_chord_t c);               /* the chord's chromatic source (theory.h): first range or second */
const cpg_scale_chord_t *cpg_scale_palette(int scale);   /* 16 chords of SCALE_*; NULL for a bad scale */
